@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;
    private bool _isIdle;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _jsModule.InvokeVoidAsync("initialize", _container, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task OnUserIdle()
    {
        if (!_isIdle)
        {
            _isIdle = true;
            await OnIdle.InvokeAsync();
        }
    }

    [JSInvokable]
    public async Task OnUserActive()
    {
        if (_isIdle)
        {
            _isIdle = false;
            await OnActive.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("dispose");
                await _jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        _dotNetRef?.Dispose();
    }
}

let timer = null;
let dotNetRef = null;
let timeoutMs = 300000;
let container = null;
const events = ["mousemove", "keydown", "click", "scroll"];

function resetTimer() {
    clearTimeout(timer);
    if (dotNetRef) {
        dotNetRef.invokeMethodAsync("OnUserActive");
    }
    timer = setTimeout(() => {
        if (dotNetRef) {
            dotNetRef.invokeMethodAsync("OnUserIdle");
        }
    }, timeoutMs);
}

export function initialize(element, ref, timeout) {
    container = element;
    dotNetRef = ref;
    timeoutMs = timeout;

    events.forEach(event => container.addEventListener(event, resetTimer, { passive: true }));

    timer = setTimeout(() => {
        if (dotNetRef) {
            dotNetRef.invokeMethodAsync("OnUserIdle");
        }
    }, timeoutMs);
}

export function dispose() {
    clearTimeout(timer);
    if (container) {
        events.forEach(event => container.removeEventListener(event, resetTimer));
    }
    dotNetRef = null;
    container = null;
}

